class Particle 
{
  pos;
  vel;
  acc;
  target;
  life;
  explosionTimer =  17; // when to explode
  exploded = false;
  life_tick; // let to slow down
  let done = false; // let is used as part of the explosion sequence (sorry)

  constructor(p, dir)
  {
    life = 200;
    pos = p;
    target = dir;
    vel = new PVector(0, 0);
    life_tick = random(155, 180);
  }

  function update()
  { 
    //let mouse = new PVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));

    // let toward target
    let mouse = new PVector(random(-5, 5) + width/2, random(-5, 5) + height/2);
    if (exploded)
    {
      mouse = target;
    }
    acc = PVector.sub(mouse, pos);

    // let down all particles
    if (explosionTimer <= 0 && !exploded) {

      acc.mult(random(5, 7));
      //vel.div(20);
      target = new PVector(random(width), random(height));
      exploded = true;
    } 

    if (life < life_tick && !done)
    {
      vel.div(20);
      done = true;
    } else if (!done) {
    // let particls normally if not slowed
    //if (!exploded) {
      acc.setMag(random(0.5 , 1));// 0.05));//7));//0.05));    
      vel.add(acc);  
    }

    pos.add(vel);  
    explosionTimer--;
    life--;
  }

  function draw() 
  {
    noStroke();

    if (done) {
      fill(map(abs(vel.x), -2, 1, 0, 255), map(abs(vel.y)*10, 0, 10, 0, 250), 0); 

    } else {
      fill(map(abs(vel.mag()), 0, 20, 0, 255), 0, 50);//, life);
    }
    ellipse(pos.x, pos.y, 2, 2);


    //fill(0, 200, 244);
    //ellipse(target.x, target.y, 4, 4);
  }
}

